/* === runtime.js === */
try{
/* 网站运行时间 */
(function () {
  // 建站日期：2026年4月1日
  var startDate = new Date('2026-04-07T00:00:00')

  function updateRuntime() {
    var now = new Date()
    var diff = now.getTime() - startDate.getTime()
    if (diff < 0) return

    // 计算年月日
    var years = now.getFullYear() - startDate.getFullYear()
    var months = now.getMonth() - startDate.getMonth()
    var days = now.getDate() - startDate.getDate()

    if (days < 0) {
      months--
      var prevMonth = new Date(now.getFullYear(), now.getMonth(), 0)
      days += prevMonth.getDate()
    }
    if (months < 0) {
      years--
      months += 12
    }

    var parts = []
    if (years > 0) parts.push(years + ' 年')
    if (months > 0) parts.push(months + ' 个月')
    if (days >= 0) parts.push(days + ' 天')

    var el = document.getElementById('site-runtime')
    if (el) el.textContent = parts.join(' ')
  }

  // 等待 DOM 就绪
  function init() {
    var footer = document.querySelector('#footer .footer-other')
    if (!footer) {
      // 如果还没加载到，延迟重试
      setTimeout(init, 500)
      return
    }
    // 移除旧的运行时间（避免 PJAX 重复）
    var old = footer.querySelector('.site-runtime-wrap')
    if (old) old.remove()
    var div = document.createElement('div')
    div.className = 'site-runtime-wrap'
    div.innerHTML = '<i class="fas fa-clock"></i> <span class="runtime-label">本站已运行</span> <span id="site-runtime"></span>'
    footer.appendChild(div)
    updateRuntime()
    // 每分钟更新一次
    setInterval(updateRuntime, 60000)
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init)
  } else {
    init()
  }

  // PJAX 导航后重新初始化
  document.addEventListener('pjax:complete', init)
})()
}catch(e){}
;
/* === calendar.js === */
try{
/*! Pink Calendar Widget — 文章标记 + 今日一言，支持 PJAX 重新初始化 */
!function(){
  var now = new Date();
  var curYear = now.getFullYear();
  var curMonth = now.getMonth();
  var today = now.getDate();
  var weekNames = ['日','一','二','三','四','五','六'];

  var postData = null;
  var postDataLoading = false;
  var activePopover = null;

  var QUOTES = [
    '今日宜：喝奶茶、写博客、看落花',
    '今日宜：听雨、发呆、写点温柔的字',
    '今日宜：早睡早起，做个好梦',
    '今日宜：给喜欢的人发一条消息',
    '今日宜：整理书桌，也整理心情',
    '今日宜：出门走走，晒晒太阳',
    '今日宜：读一本搁置很久的书',
    '今日宜：吃一块小蛋糕犒劳自己',
    '今日宜：把心事写进博客里',
    '今日宜：听一首老歌，想起一个人',
    '今日宜：种一盆花，等它慢慢开',
    '今日宜：关掉手机，安静一小时',
    '今日宜：试着做一道新菜',
    '今日宜：收集一片好看的落叶',
    '今日宜：给未来的自己写封信',
    '今日宜：什么都不做，也很好',
    '今日宜：看一部治愈系动画',
    '今日宜：泡一杯热茶，慢慢喝',
    '今日宜：把房间打扫得干干净净',
    '今日宜：去见一个很久没见的朋友',
    '今日宜：学一点新东西，哪怕很小',
    '今日宜：对着镜子笑一笑',
    '今日宜：把喜欢的句子抄下来',
    '今日宜：抬头看看云的形状',
    '今日宜：给自己买一束花',
    '今日宜：早点休息，晚安',
    '今日宜：许一个小小的愿望',
    '今日宜：原谅昨天的自己',
    '今日宜：认真吃一顿早餐',
    '今日宜：记录今天的一个小确幸',
    '今日宜：慢慢来，不着急'
  ];

  function pad2(n) { return n < 10 ? '0' + n : '' + n; }
  function dayKey(y, m, d) { return y + '-' + pad2(m + 1) + '-' + pad2(d); }

  function getQuote() {
    var seed = curYear * 10000 + (curMonth + 1) * 100 + today;
    return QUOTES[seed % QUOTES.length];
  }

  function fetchPostData(cb) {
    if (postData) { cb(postData); return; }
    if (postDataLoading) return;
    postDataLoading = true;
    fetch('/calendar.json').then(function(r) { return r.json(); }).then(function(data) {
      postData = data || {};
      postDataLoading = false;
      cb(postData);
    }).catch(function() {
      postData = {};
      postDataLoading = false;
    });
  }

  function closePopover() {
    if (activePopover) {
      activePopover.remove();
      activePopover = null;
      document.removeEventListener('click', onDocClick, true);
    }
  }

  function onDocClick(e) {
    if (activePopover && !activePopover.contains(e.target) && !e.target.closest('.has-post')) {
      closePopover();
    }
  }

  function showPopover(td, posts) {
    closePopover();
    var pop = document.createElement('div');
    pop.className = 'cal-post-popover';
    var html = '<div class="cal-pop-header">🌸 这天发布了 ' + posts.length + ' 篇文章</div>';
    posts.forEach(function(p) {
      html += '<a class="cal-pop-item" href="' + p.url + '">' + p.title + '</a>';
    });
    pop.innerHTML = html;
    document.body.appendChild(pop);

    var rect = td.getBoundingClientRect();
    var popW = pop.offsetWidth;
    var popH = pop.offsetHeight;
    var margin = 8;
    var gap = 6;

    var top = rect.top - popH - gap;
    if (top < margin) {
      top = rect.bottom + gap;
      var avail = window.innerHeight - top - margin;
      if (popH > avail) {
        pop.style.maxHeight = Math.max(120, avail) + 'px';
        pop.style.overflowY = 'auto';
      }
    }

    var left = rect.left + rect.width / 2 - popW / 2;
    if (left < margin) left = margin;
    if (left + popW > window.innerWidth - margin) left = window.innerWidth - popW - margin;

    pop.style.top = top + 'px';
    pop.style.left = left + 'px';

    activePopover = pop;
    setTimeout(function() {
      document.addEventListener('click', onDocClick, true);
    }, 0);
  }

  function render(y, m, data) {
    var firstDay = new Date(y, m, 1).getDay();
    var daysInMonth = new Date(y, m + 1, 0).getDate();
    var prevDays = new Date(y, m, 0).getDate();
    var isCurMonth = (y === curYear && m === curMonth);
    var html = '';

    html += '<div class="calendar-nav">';
    html += '<button class="cal-prev" title="上月" aria-label="上个月"><i class="fas fa-chevron-left"></i></button>';
    html += '<span class="calendar-title">' + y + '年' + (m + 1) + '月</span>';
    html += '<button class="cal-next" title="下月" aria-label="下个月"><i class="fas fa-chevron-right"></i></button>';
    html += '</div>';

    html += '<table class="pink-calendar"><thead><tr>';
    for (var w = 0; w < 7; w++) html += '<th>' + weekNames[w] + '</th>';
    html += '</tr></thead><tbody>';

    var day = 1;
    var nextDay = 1;
    for (var i = 0; i < 6; i++) {
      if (i > 0 && day > daysInMonth) break;
      html += '<tr>';
      for (var j = 0; j < 7; j++) {
        if (i === 0 && j < firstDay) {
          html += '<td class="other-month"><span>' + (prevDays - firstDay + j + 1) + '</span></td>';
        } else if (day > daysInMonth) {
          html += '<td class="other-month"><span>' + (nextDay++) + '</span></td>';
        } else {
          var key = dayKey(y, m, day);
          var posts = data ? data[key] : null;
          var cls = '';
          if (isCurMonth && day === today) cls = ' today';
          if (posts && posts.length) cls += ' has-post';
          var tip = posts && posts.length ? (posts.length === 1 ? posts[0].title : '这天发布了 ' + posts.length + ' 篇文章') : '';
          html += '<td class="' + cls.trim() + '"' + (tip ? ' title="' + tip.replace(/"/g, '&' + 'quot;') + '"' : '') + '>';
          html += '<span' + (isCurMonth && day === today ? ' class="today-span"' : '') + '>' + day + '</span>';
          if (posts && posts.length) {
            html += '<i class="cal-post-dot' + (posts.length > 1 ? ' multi' : '') + '">' + (posts.length > 1 ? posts.length : '') + '</i>';
          }
          html += '</td>';
          day++;
        }
      }
      html += '</tr>';
    }
    html += '</tbody></table>';

    html += '<div class="cal-quote"><i class="fas fa-feather-alt"></i><span>' + getQuote() + '</span></div>';

    return html;
  }

  function build() {
    var aside = document.querySelector('#aside-content .sticky_layout') || document.querySelector('#aside-content');
    var announcement = document.querySelector('.card-announcement');
    if (!aside) return;

    var old = aside.querySelector('.card-calendar');
    if (old) old.remove();
    closePopover();

    var card = document.createElement('div');
    card.className = 'card-widget card-calendar';
    card.innerHTML = '<div class="item-headline"><i class="fas fa-calendar-alt"></i><span>日历</span></div><div class="calendar-body"></div>';

    if (announcement && announcement.parentNode === aside) {
      aside.insertBefore(card, announcement);
    } else {
      aside.insertBefore(card, aside.firstChild);
    }

    var body = card.querySelector('.calendar-body');
    var vy = curYear, vm = curMonth;

    function draw() {
      body.innerHTML = render(vy, vm, postData);
      bindNav();
      bindPostDays();
    }

    draw();
    if (!postData) {
      fetchPostData(function() { draw(); });
    }

    function bindNav() {
      var prev = card.querySelector('.cal-prev');
      var next = card.querySelector('.cal-next');
      if (prev) { prev.onclick = function() { vm--; if (vm < 0) { vm = 11; vy--; } closePopover(); draw(); }; }
      if (next) { next.onclick = function() { vm++; if (vm > 11) { vm = 0; vy++; } closePopover(); draw(); }; }
    }

    function bindPostDays() {
      var tds = card.querySelectorAll('.has-post');
      for (var i = 0; i < tds.length; i++) {
        (function(td) {
          td.onclick = function(e) {
            e.stopPropagation();
            var num = parseInt(td.querySelector('span').textContent, 10);
            var key = dayKey(vy, vm, num);
            var posts = postData && postData[key];
            if (!posts || !posts.length) return;
            if (posts.length === 1) {
              location.href = posts[0].url;
            } else {
              showPopover(td, posts);
            }
          };
        })(tds[i]);
      }
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', build);
  } else {
    build();
  }

  document.addEventListener('pjax:complete', build);
}();
}catch(e){}
;
