/* === mobile-toc.js === */
try{
/*! Mobile TOC — 手机端目录默认隐藏，按钮切换开合 */
(function () {
  'use strict';

  function init() {
    var toc = document.getElementById('card-toc');
    if (!toc) return;

    // 确保手机端初始状态：面板关闭 + 子目录折叠
    if (window.innerWidth <= 900) {
      toc.classList.remove('open');
      toc.setAttribute('aria-expanded', 'false');
      var content = toc.querySelector('.toc-content');
      if (content) content.classList.remove('is-expand');
    } else {
      toc.setAttribute('aria-expanded', 'true');
    }

    // 监听面板开关，同步 aria-expanded + 子目录折叠
    var observer = new MutationObserver(function () {
      var isOpen = toc.classList.contains('open');
      toc.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      if (isOpen && window.innerWidth <= 900) {
        var content = toc.querySelector('.toc-content');
        if (content) content.classList.remove('is-expand');
      }
    });
    observer.observe(toc, { attributes: true, attributeFilter: ['class'] });

    // 点击面板外部关闭
    document.addEventListener('click', function (e) {
      if (window.innerWidth > 900) return;
      if (!toc.classList.contains('open')) return;
      if (toc.contains(e.target)) return;
      if (e.target.closest('#mobile-toc-button')) return;
      toc.classList.remove('open');
    });
  }

  // 初始化 + PJAX 兼容
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
  document.addEventListener('pjax:complete', init);
})();
}catch(e){}
;
/* === recent-post-collapse.js === */
try{
/*! 侧边栏卡片折叠 — 最新文章 / 最新评论，默认收起，点击标题展开，记忆偏好 */
(function () {
  'use strict';

  // 需要折叠的卡片选择器 → localStorage 键名
  var CARDS = [
    { selector: '.card-recent-post', key: 'collapse-recent-post' },
    { selector: '#card-newest-comments', key: 'collapse-newest-comments' }
  ];

  function getPref(key) {
    try {
      var v = localStorage.getItem(key);
      return v === null ? '1' : v;
    } catch (e) { return '1'; }
  }

  function setPref(key, v) {
    try { localStorage.setItem(key, v); } catch (e) {}
  }

  function initCard(cfg) {
    var card = document.querySelector(cfg.selector);
    if (!card) return;
    if (card.querySelector('.collapse-toggle')) return;

    var headline = card.querySelector('.item-headline');
    if (!headline) return;

    var toggle = document.createElement('i');
    toggle.className = 'fas fa-chevron-down collapse-toggle';
    headline.appendChild(toggle);

    if (getPref(cfg.key) === '1') card.classList.add('is-collapsed');

    headline.addEventListener('click', function () {
      var collapsed = card.classList.toggle('is-collapsed');
      setPref(cfg.key, collapsed ? '1' : '0');
    });
  }

  function init() {
    CARDS.forEach(initCard);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
  document.addEventListener('pjax:complete', init);
})();
}catch(e){}
;
/* === pinned-post.js === */
try{
(function () {
  'use strict';

  var PINNED_POSTS = [
    {
      url: '/posts/56950e97.html',
      title: 'AVG资源汇总指路站（文游+单机+工具）',
      desc: 'BLG·乙女向·Gal·综合单机·工具类一站式资源导航',
      cover: '/img/juugou/image44.webp',
      tag: '资源汇总'
    }
  ];

  function isHome() {
    var p = location.pathname;
    return p === '/' || p === '/index.html';
  }

  function buildCard(post) {
    var card = document.createElement('div');
    card.className = 'card-widget card-pinned';

    var inner = document.createElement('div');
    inner.className = 'pinned-inner';

    var badge = document.createElement('div');
    badge.className = 'pinned-badge';
    badge.innerHTML = '<i class="fas fa-thumbtack"></i> 置顶';

    var link = document.createElement('a');
    link.className = 'pinned-link';
    link.href = post.url;
    link.title = post.title;

    var cover = document.createElement('div');
    cover.className = 'pinned-cover';
    var img = document.createElement('img');
    img.src = post.cover;
    img.alt = post.title;
    img.loading = 'lazy';
    img.onerror = function () { cover.style.display = 'none'; };
    cover.appendChild(img);

    var info = document.createElement('div');
    info.className = 'pinned-info';

    var title = document.createElement('div');
    title.className = 'pinned-title';
    title.textContent = post.title;

    var desc = document.createElement('div');
    desc.className = 'pinned-desc';
    desc.textContent = post.desc;

    var meta = document.createElement('div');
    meta.className = 'pinned-meta';
    meta.innerHTML = '<span class="pinned-tag"><i class="fas fa-tag"></i> ' + post.tag + '</span><span class="pinned-go">前往阅读 <i class="fas fa-arrow-right"></i></span>';

    info.appendChild(title);
    info.appendChild(desc);
    info.appendChild(meta);
    link.appendChild(cover);
    link.appendChild(info);
    inner.appendChild(badge);
    inner.appendChild(link);
    card.appendChild(inner);

    return card;
  }

  function init() {
    if (!isHome()) return;
    var aside = document.getElementById('aside-content');
    if (!aside) return;
    if (aside.querySelector('.card-pinned')) return;

    var announcement = aside.querySelector('.card-announcement');
    if (!announcement) return;

    var frag = document.createDocumentFragment();
    PINNED_POSTS.forEach(function (post) {
      frag.appendChild(buildCard(post));
    });
    announcement.parentNode.insertBefore(frag, announcement.nextSibling);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
  document.addEventListener('pjax:complete', init);
})();
}catch(e){}
;
